def caesar_shift(text, shift):
    result = ""
    for ch in text:
        if 'a' <= ch <= 'z':
            result += chr((ord(ch) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= ch <= 'Z':
            result += chr((ord(ch) - ord('A') + shift) % 26 + ord('A'))
        else:
            result += ch
    return result

for shift in range(26):
    print(f"shift {shift:2d}: {caesar_shift(cipher, shift)}")

def rail_fence_decrypt(cipher, rows):
    n = len(cipher)
    fence = [[''] * n for _ in range(rows)]
    r, step = 0, 1
    for c in range(n):
        fence[r][c] = '*'
        if r == 0:
            step = 1
        elif r == rows - 1:
            step = -1
        r += step
    idx = 0
    for i in range(rows):
        for j in range(n):
            if fence[i][j] == '*':
                fence[i][j] = cipher[idx]
                idx += 1
    result = []
    r, step = 0, 1
    for c in range(n):
        result.append(fence[r][c])
        if r == 0:
            step = 1
        elif r == rows - 1:
            step = -1
        r += step
    return ''.join(result)

cipher = "WECRERDSOEEAIVD"
for rows in range(2, 11):
    print(f"rows={rows}: {rail_fence_decrypt(cipher, rows)}")
